const SIZE_MAP = {
  'extra small': 'XS', 'xs': 'XS',
  'small': 'S', 's': 'S',
  'medium': 'M', 'm': 'M',
  'large': 'L', 'l': 'L',
  'extra large': 'XL', 'xl': 'XL',
  'double extra large': 'XXL', 'xxl': 'XXL', '2xl': 'XXL',
};

const COLOR_MAP = {
  'black': 'BLK',
  'white': 'WHT',
  'yellow': 'YLW',
  'red': 'RED',
  'blue': 'BLU',
  'green': 'GRN',
  'gray': 'GRY',
  'grey': 'GRY',
};

const toSizeCode = (v) => SIZE_MAP[String(v ?? '').trim().toLowerCase()] ?? null;
const toColorCode = (v) => COLOR_MAP[String(v ?? '').trim().toLowerCase()] ?? null;

const output = $input.first().json.output ?? $input.first().json;
const exchanges = output.exchanges ?? [];

return exchanges.map((ex) => {
  const productCode = String(ex.original_sku ?? '').split('-')[0];
  const sizeCode = toSizeCode(ex.requested_size);
  const colorCode = toColorCode(ex.requested_color);
  const valid = Boolean(productCode && sizeCode && colorCode);

  return {
    json: {
      original_sku: ex.original_sku,
      requested_size: ex.requested_size,
      requested_color: ex.requested_color,
      requested_sku: valid ? `${productCode}-${sizeCode}-${colorCode}` : null,
      valid
    }
  };
});

const text = $input.first().json.chatInput || '';

// Find a number that follows the word "order" (optionally with #, no., number, id)
const match = text.match(/order\s*(?:#|no\.?|number|id)?\s*[:#-]?\s*#?(\d{3,})/i);

// Fallback: any standalone 3+ digit number in the message
const fallback = text.match(/\b\d{3,}\b/);

const order_number = match ? match[1] : (fallback ? fallback[0] : null);

return [
  {
    json: {
      sessionId: $input.first().json.sessionId,
      chatInput: text,
      status: order_number ? 'found' : 'not found'
    }
  }
];

