// n8n Code Node - Run Once for Each Item
// Adjust this to match the field that holds the user's message
const rawMessage = $input.first().json.chatInput;

// ---------- Normalize ----------
function normalize(text) {
  return String(text)
    .toLowerCase()
    .trim()
    // remove emojis & punctuation, keep letters/numbers/spaces/apostrophes
    .replace(/[^\p{L}\p{N}\s']/gu, ' ')
    // collapse repeated letters: "nooo" -> "no", "yesss" -> "yes"
    .replace(/(.)\1{2,}/g, '$1')
    .replace(/\s+/g, ' ')
    .trim();
}

const msg = normalize(rawMessage);

// ---------- Patterns ----------
const noPatterns = [
  /\bno+\b/, /\bnope\b/, /\bnah\b/, /\bn\b/,
  /\bwait\b/, /\bstop\b/, /\bhold on\b/, /\bhold up\b/,
  /\bdon'?t\b/, /\bdo not\b/, /\bdont\b/,
  /\bcancel that\b/, /\bnever ?mind\b/, /\bnot (now|yet|sure)\b/,
  /\bchanged my mind\b/, /\bkeep (it|my order)\b/, /\bdon'?t cancel\b/
];

const yesPatterns = [
  /\byes+\b/, /\byeah\b/, /\byep\b/, /\byup\b/, /\by\b/,
  /\bsure\b/, /\bi'?m sure\b/, /\bim sure\b/, /\bok(ay)?\b/,
  /\bconfirm(ed)?\b/, /\bproceed\b/, /\bgo ahead\b/,
  /\bdefinitely\b/, /\babsolutely\b/, /\bof course\b/,
  /\bcancel (it|my order|the order)\b/
];

// ---------- Decision ----------
// "No" patterns are checked first, so "no, wait", "don't", and
// "I'm not sure" are never mistaken for a "yes".
let user_reply = 'unknown';

if (noPatterns.some(p => p.test(msg))) {
  user_reply = 'no';
} else if (yesPatterns.some(p => p.test(msg))) {
  user_reply = 'yes';
}

return {
  json: {
    ...$json,
    user_reply          // "yes" | "no" | "unknown"

  }
};

// Safely read a value from a node (returns '' if the node didn't run or the field is missing)
const safeGet = (fn) => {
  try { return fn() || ''; } catch (e) { return ''; }
};

// Collect text from every place the user may have typed the email
const sources = [
  safeGet(() => $('When chat message received').first().json.chatInput),
  safeGet(() => $('Text Classifier').first().json.chatInput),
  safeGet(() => $('ASK order number2').first().json.data.text),
  safeGet(() => $input.first().json.chatInput),
];

const text = sources.filter(Boolean).join(' ');

// Find any email address in the combined text
const match = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
const email = match ? match[0].toLowerCase() : null;

return [
  {
    json: {
      sessionId: safeGet(() => $('When chat message received').first().json.sessionId),
      chatInput: text,
      email: email,
      status: email ? 'found' : 'not found'
    }
  }
];

